public static IReadOnlyList<CapabilityDeclaration> Capabilities { get; } = Array.AsReadOnly(new CapabilityDeclaration[] { new CapabilityDeclaration(@"buildings.inspect", @"skylines_building_inspect", @"1", @"Inspect one current building by the native information panel's published selection or a full instance/generation/index/version reference. Returns real transform, prefab metadata and bounded direct relations; never changes selection, refreshes the panel, builds, or proves placement eligibility, reachability or operation.", @"read", @"urn:skylineslink:contract:building-inspection-query:1", @"urn:skylineslink:contract:building-inspection:1"), new CapabilityDeclaration(@"system.context", @"skylines_context", @"2", @"读取游戏实例、本次加载作用域和可用状态；已验证就绪的世界可没有稳定城市ID。不启动游戏或加载存档。", @"read", @"urn:skylineslink:contract:empty:1", @"urn:skylineslink:contract:context:2"), new CapabilityDeclaration(@"operations.get", @"skylines_operation_get", @"5", @"按操作 ID 或原提交键查询操作；source缺省live，history读取已发布的持久终态。查询不重放，未覆盖或不可用不表示可以重提。", @"read", @"urn:skylineslink:contract:operation-query:3", @"urn:skylineslink:contract:operation-lookup:4"), new CapabilityDeclaration(@"guidance.search", @"skylines_guidance_search", @"1", @"Search static, bundled public product guidance. This describes declared capabilities only, without a guarantee of current game availability or qualification. Never starts the game.", @"read", @"urn:skylineslink:contract:guidance-search-query:1", @"urn:skylineslink:contract:guidance-search-result:1"), new CapabilityDeclaration(@"guidance.get", @"skylines_guidance_get", @"1", @"Read a static, bundled public product guide. Capability references describe declared schemas only, without a guarantee of current game availability or qualification. Never starts the game.", @"read", @"urn:skylineslink:contract:guidance-query:1", @"urn:skylineslink:contract:guidance-document:1"), new CapabilityDeclaration(@"capabilities.describe", @"skylines_capability_describe", @"1", @"Read exact declared input and output schemas from static, bundled product metadata. This does not guarantee current game availability or qualification. Never starts the game.", @"read", @"urn:skylineslink:contract:capability-query:1", @"urn:skylineslink:contract:capability-description:1"), new CapabilityDeclaration(@"tasks.stop", @"skylines_task_stop", @"1", @"请求停止指定任务的后续工作并立即返回原停止决定。pending表示持久确认仍在进行，回执不代表所有已提交动作已停止；取消等待不回滚停止请求。环境不支持时明确返回不可用。", @"write", @"urn:skylineslink:contract:task-stop-query:1", @"urn:skylineslink:contract:task-stop-result:1"), new CapabilityDeclaration(@"tasks.stop.get", @"skylines_task_stop_decision_get", @"1", @"按任务与原预期控制版本读取原停止决定。source缺省live，显式history仅读取已确认出版事实；未覆盖不表示未执行。查询不会发出停止请求，也不自动回退来源。", @"read", @"urn:skylineslink:contract:task-stop-decision-query:1", @"urn:skylineslink:contract:task-stop-decision-lookup:1"), new CapabilityDeclaration(@"system.modules.get", @"skylines_module_runtime_get", @"1", @"Read a bounded snapshot of the current module-loader registry. Rows describe observed runtime state, not all installed or subscribed packages, enabled modules, or a health verdict.", @"read", @"urn:skylineslink:contract:module-runtime-query:1", @"urn:skylineslink:contract:module-runtime-page:1"), new CapabilityDeclaration(@"city.overview", @"skylines_city_overview", @"2", @"Read native city population, player money, selected simulation speed and game clock in one bounded observation of the current loaded city. Includes loading scope, capture frames, units and missing reasons. Source update times, pause causes and actual advancement remain unknown; never loads a city or changes simulation.", @"read", @"urn:skylineslink:contract:empty:1", @"urn:skylineslink:contract:city-overview:2") });
public static JToken GetSchema(string id) => Schemas.TryGetValue(id, out var schema) ? schema.DeepClone() : throw new ArgumentException("未知schema", nameof(id));
public static ValidationResult Validate(string id, JToken value, RegisteredBinding? binding = null) => ContractValidator.Validate(id, value, binding, Models, Schemas, Capabilities);
public static JToken ParseAndValidate(string id, string json, RegisteredBinding? binding = null) { var value = id == SchemaIds.OperationHistoryCheckpointV2 ? ContractJson.ParseHistoryCheckpointV2(json) : ContractJson.Parse(json); Require(id, value, binding); return value; }
public static void Require(string id, JToken value, RegisteredBinding? binding = null) { var result = Validate(id, value, binding); if (!result.Valid) throw new ContractValidationException(result.Issues); }
internal static void RequireHistorySource(JToken value) { var root=Models[SchemaIds.OperationHistoryCheckpoint]; var model=root.Properties["source"]; var result=ContractValidator.Validate(SchemaIds.OperationHistoryCheckpoint,value,null,Models,Schemas,Capabilities,model); if(!result.Valid) throw new ContractValidationException(result.Issues); }
internal static void RequireHistoryRecord(JToken value) { var root=Models[SchemaIds.OperationHistoryCheckpoint]; var model=root.Properties["records"].Items!; var result=ContractValidator.Validate(SchemaIds.OperationHistoryCheckpoint,value,null,Models,Schemas,Capabilities,model); if(!result.Valid) throw new ContractValidationException(result.Issues); }
